def published_slugs() -> set[str]:
    """Slugs from r01–r917 only. This mill's own later rounds are not clones."""
    out: set[str] = set()
    if not FACTORY_DIR.is_dir():
        return out
    rnd_pat = re.compile(r"batch-r(\d+)[a-z]*\.jsonl$")
    id_pat = re.compile(r"mdb-r\d+-(.+)$")
    for path in FACTORY_DIR.glob("batch-r*.jsonl"):
        match_r = rnd_pat.match(path.name)
        if not match_r:
            continue
        if int(match_r.group(1)) >= CATALOG_FIRST:
            continue
        for line in path.read_text().splitlines():
            if not line.strip():
                continue
            rec = json.loads(line)
            match = id_pat.match(rec.get("id", ""))
            if match:
                out.add(match.group(1))
    return out


def notes_for(round_n: int, a: dict, b: dict) -> str:
    ea = f"mdb-r{round_n}-{a['slug']}"
    eb = f"mdb-r{round_n}-{b['slug']}"
    novel = 87 + (round_n % 6)
    return f"""# NOTES-r{round_n} monorepo-dep-bump-factory

Novel coverage: {novel}%

Two designed episodes (quota 2). Surfaces: {a['surface']} ({a['pkg']} {a['api_break']}); {b['surface']} ({b['pkg']} {b['api_break']}).
Not a pin-file mill and not libNNNN recycle. Distinct from r01–r917 clones (ban openems-xml-leftover-fdtd / siliconcompiler-py-leftover-target; no pnpm/zod/changesets/maven/gradle/go.work/uv/poetry/turbo/cargo-patch/yarn/bun/nx).

| id | seed | first apply | plan change | terminal |
|---|---|---|---|---|
| {ea} | {a['surface']} | nested {a['new']} | SoT {a['new']} + {a['api_break']} | {'leftover-workspace fail; ' + a['left'] + ' ' + a.get('left_ver', a['old']) if a['fail'] else 'success; ' + a['left'] + ' leftover'} |
| {eb} | {b['surface']} | nested {b['new']} | SoT {b['new']} + {b['api_break']} | {'leftover-workspace fail; ' + b['left'] + ' ' + b.get('left_ver', b['old']) if b['fail'] else 'success; ' + b['left'] + ' leftover'} |

## Step counts
- ep1: 18. Nested apply 6–7; plan change 8; API break 10–12; leftover {a['left']}.
- ep2: 18. Nested apply 6–7; plan change 8; API break 10–12; leftover-workspace fail {b['left']}.

## decision_basis audit
Every step starts Plan:/Observation:/Reflection:, ≤240 chars.
No thought / chain_of_thought / scratch / inner_monologue. No spike_events.
No sim_or_real: real. Plants `{a['plant']}` and `{b['plant']}`.

## Weaknesses / next
Keep unique leftover plots. Ban r01–r917 clones, libNNNN, Mix/Elixir, Conan/Hunter/vcpkg/Meson wrap/CMake FetchContent.
"""


def make(
    slug: str,
    plant: str,
    surface: str,
    pkg: str,
    old: str,
    new: str,
    fail: bool,
    pin: str,
    sot_old: str,
    sot_new: str,
    nest_old: str,
    nest_new: str,
    api_old: str,
    api_new: str,
    api_break: str,
    tool: str,
    test: str,
    ws: str,
    ext: str,
) -> dict:
    return P(
        slug,
        plant,
        surface,
        pkg,
        old,
        new,
        fail,
        pin,
        f"apps/api/{pin}",
        sot_old,
        sot_new,
        nest_old,
        nest_new,
        api_old,
        api_new,
        api_break,
        tool,
        test,
        ws,
        f"apps/api/{plant}.{ext}",
    )


